// Archi - Navigateur : pilote l'Edge d'Archi (navigateur.py) et renvoie la capture s'il y en a une
const cp = require('child_process');
const fs = require('fs');
const i = $('Execute Workflow Trigger').first().json;
const f = ($env.ARCHI_BASE || '') + '/navigateur/demande_' + Date.now() + '.json';
fs.writeFileSync(f, JSON.stringify({ action: i.action || '', cible: i.cible || '', valeur: i.valeur || '' }), 'utf8');
let r;
try {
  const o = cp.execFileSync(($env.ARCHI_SERVEUR_PY || (($env.ARCHI_DEPOT || '') + '/serveur/venv/Scripts/python.exe')),
    [($env.ARCHI_DEPOT || '') + '/serveur/navigateur.py', '--fichier', f],
    { timeout: 120000, windowsHide: true, env: Object.assign({}, require('process').env, { PYTHONIOENCODING: 'utf-8' }) }).toString('utf8').trim().split(/\r?\n/).pop();
  r = JSON.parse(o);
} catch (e) { r = { ok: false, phrase_pour_utilisateur: 'Mon navigateur ne répond pas BOSS.', erreur: String(e.message || e).slice(0, 200) }; }
try { fs.unlinkSync(f); } catch (e) {}
const item = { json: r };
if (r.capture && fs.existsSync(r.capture)) {
  if ($env.TELEGRAM_BOT_TOKEN && $env.ARCHI_TELEGRAM_CHAT_ID) {
    item.binary = { capture: await this.helpers.prepareBinaryData(fs.readFileSync(r.capture), 'capture.png', 'image/png') };
    r.capture_envoyee = 'oui, l’utilisateur la voit sur Telegram';
  } else {
    // sans bot Telegram : la capture reste sur le PC, on dit ou elle est
    r.capture_enregistree = 'La capture est enregistrée sur le PC (Telegram n’est pas branché, elle n’est pas envoyée) : ' + r.capture;
  }
}
return [item];

const r = Object.assign({}, $('Navigateur').first().json);
delete r.capture;
return [{ json: r }];

const cp = require('child_process');
const p = cp.spawn(($env.ARCHI_SERVEUR_PY || (($env.ARCHI_DEPOT || '') + '/serveur/venv/Scripts/python.exe')), [($env.ARCHI_DEPOT || '') + '/serveur/navigateur.py', 'surveiller_tout'], { detached: true, stdio: 'ignore', windowsHide: true, env: Object.assign({}, require('process').env, { PYTHONIOENCODING: 'utf-8' }) });
p.unref();
return [{ json: { lance: 'surveillance' } }];
